window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-705ed753898d27c9"]={"versions": [{"id": "FIG-705ed753898d27c9", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Inklusionsdiagramm (Dateistruktur/Header-Abhängigkeiten) für AUTOSAR Classic BSW-Module zur Darstellung der Datei- und Include-Beziehungen einer C-Quelldatei im Kontext des BSW Schedulers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Entitäten (Dateien):\n<ul class=\"fig-list\"><li><code>&lt;ModulePrefix&gt;.c</code>: Haupt-C-Quelldatei der BSW-Implementierung.\n</li><li><code>&lt;ModulePrefix&gt;.h</code>: Modulspezifischer Haupt-Header (öffentliche Deklarationen/Schnittstellen).\n</li><li><code>&lt;ModulePrefix&gt;_cfg.h</code>: Konfigurations-Header des Moduls (Pre-Compile-/Build-Time-Konfigurationsparameter).\n</li><li><code>SchM_&lt;ModulePrefix&gt;.h</code>: Modulspezifischer BSW-Scheduler-Header (stellt API-Makros/Funktionen für Exklusive Bereiche und Scheduler-Integration bereit).\n</li><li><code>other1.h</code> / <code>other2.h</code>: Weitere inkludierte Header-Dateien (z. B. Standardtypen oder externe Modulschnittstellen).\n</li></ul>\n</li><li>Beziehungen:\n<ul class=\"fig-list\"><li>Gestrichelte gerichtete Abhängigkeitspfeile mit dem Stereotyp <code>«includes»</code> von <code>&lt;ModulePrefix&gt;.c</code> ausgehend zu allen genannten Header-Dateien.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsschema zur Übersetzungszeit (Kompilierung). <code>&lt;ModulePrefix&gt;.c</code> bindet über <code>#include</code>-Direktiven die modulspezifischen Header <code>&lt;ModulePrefix&gt;.h</code>, <code>&lt;ModulePrefix&gt;_cfg.h</code>, den Scheduler-Header <code>SchM_&lt;ModulePrefix&gt;.h</code> sowie modulabhängig weitere Header (<code>other1.h</code>, <code>other2.h</code>) ein. Es wird kein dynamischer Kontrollfluss zur Laufzeit dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Inklusionsstruktur definiert die verbindliche Einbindung des BSW-Schedulers auf Modulebene: Ein BSW-Modul bindet nicht direkt generische Scheduler-Header ein, sondern ausschließlich die modulspezifische Schnittstellendatei <code>SchM_&lt;ModulePrefix&gt;.h</code>. Ergänzend werden die eigene Moduldeklaration (<code>&lt;ModulePrefix&gt;.h</code>) und Konfigurationsdatei (<code>&lt;ModulePrefix&gt;_cfg.h</code>) inkludiert, um Typen und Konfigurationsparameter für die Implementierung aufzulösen.</p>"}, {"id": "FIG-55c6aefbc2a31a8c", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Inklusionsdiagramm (Dateistruktur/Header-Abhängigkeiten) für AUTOSAR Classic BSW-Module zur Darstellung der Datei- und Include-Beziehungen einer C-Quelldatei im Kontext des BSW Schedulers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Entitäten (Dateien):\n<ul class=\"fig-list\"><li><code>&lt;ModulePrefix&gt;.c</code>: Haupt-C-Quelldatei der BSW-Implementierung.\n</li><li><code>&lt;ModulePrefix&gt;.h</code>: Modulspezifischer Haupt-Header (öffentliche Deklarationen/Schnittstellen).\n</li><li><code>&lt;ModulePrefix&gt;_cfg.h</code>: Konfigurations-Header des Moduls (Pre-Compile-/Build-Time-Konfigurationsparameter).\n</li><li><code>SchM_&lt;ModulePrefix&gt;.h</code>: Modulspezifischer BSW-Scheduler-Header (stellt API-Makros/Funktionen für Exklusive Bereiche und Scheduler-Integration bereit).\n</li><li><code>other1.h</code> / <code>other2.h</code>: Weitere inkludierte Header-Dateien (z. B. Standardtypen oder externe Modulschnittstellen).\n</li></ul>\n</li><li>Beziehungen:\n<ul class=\"fig-list\"><li>Gestrichelte gerichtete Abhängigkeitspfeile mit dem Stereotyp <code>«includes»</code> von <code>&lt;ModulePrefix&gt;.c</code> ausgehend zu allen genannten Header-Dateien.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusionsschema zur Übersetzungszeit (Kompilierung). <code>&lt;ModulePrefix&gt;.c</code> bindet über <code>#include</code>-Direktiven die modulspezifischen Header <code>&lt;ModulePrefix&gt;.h</code>, <code>&lt;ModulePrefix&gt;_cfg.h</code>, den Scheduler-Header <code>SchM_&lt;ModulePrefix&gt;.h</code> sowie modulabhängig weitere Header (<code>other1.h</code>, <code>other2.h</code>) ein. Es wird kein dynamischer Kontrollfluss zur Laufzeit dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Inklusionsstruktur definiert die verbindliche Einbindung des BSW-Schedulers auf Modulebene: Ein BSW-Modul bindet nicht direkt generische Scheduler-Header ein, sondern ausschließlich die modulspezifische Schnittstellendatei <code>SchM_&lt;ModulePrefix&gt;.h</code>. Ergänzend werden die eigene Moduldeklaration (<code>&lt;ModulePrefix&gt;.h</code>) und Konfigurationsdatei (<code>&lt;ModulePrefix&gt;_cfg.h</code>) inkludiert, um Typen und Konfigurationsparameter für die Implementierung aufzulösen.</p>"}], "trans": [{"from": "FIG-705ed753898d27c9", "to": "FIG-55c6aefbc2a31a8c", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
